const {chromium}=require('playwright'),http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const root=path.resolve('open-world'),out='/tmp/moonkatty-first-frame';fs.mkdirSync(out,{recursive:true});
const server=http.createServer((req,res)=>{let p=path.resolve(root,'.'+decodeURIComponent(req.url.split('?')[0]));if(p===root)p=path.join(root,'index.html');if(!p.startsWith(root+path.sep)){res.writeHead(403).end();return;}fs.readFile(p,(err,b)=>{if(err){res.writeHead(404).end();return;}res.setHeader('Content-Type',({'.js':'text/javascript','.html':'text/html','.css':'text/css','.jpg':'image/jpeg','.webp':'image/webp'})[path.extname(p)]||'application/octet-stream');res.end(b);});});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));let browser;const report={commit:process.env.GITHUB_SHA,scope:'Actual Chromium WebGL frame, reduced-resolution software-GPU CI, not device performance',errors:[]};try{browser=await chromium.launch({headless:true,args:['--enable-unsafe-swiftshader','--use-angle=swiftshader']});const context=await browser.newContext({viewport:{width:960,height:540},deviceScaleFactor:.75}),page=await context.newPage();page.setDefaultTimeout(90000);page.on('pageerror',e=>{report.errors.push(e.message);console.log('Page error',e.message);});await page.goto(`http://127.0.0.1:${server.address().port}/?lang=ru`,{waitUntil:'domcontentloaded'});console.log('DOM loaded');await page.waitForFunction(()=>window.OpenWorldPreview?.snapshot().ready||document.body.dataset.error);report.snapshot=await page.evaluate(()=>window.OpenWorldPreview?.snapshot());report.error=await page.getAttribute('body','data-error');console.log('Ready state',report.snapshot?.ready,report.error);if(report.snapshot?.ready)await page.evaluate(()=>{OpenWorldPreview.pause(true);document.getElementById('pausePanel').hidden=true;});await page.screenshot({path:path.join(out,'01-first-low-resolution-frame.png'),timeout:90000});console.log('First frame saved');}catch(error){report.error=error.stack;throw error;}finally{fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));if(browser)await browser.close();await new Promise(r=>server.close(r));}})();
